function records=hash_files(files),records=repmat(struct('path','','sha256',''),numel(files),1);for k=1:numel(files),records(k)=struct('path',files{k},'sha256',sha(files{k}));end,end
function assert_expected(records,expected),assert(hashes_match(records,expected),'Frozen hash mismatch before D1 runtime.');end
function ok=hashes_match(records,expected),ok=numel(records)==numel(expected);for k=1:numel(records),ok=ok&&strcmp(records(k).sha256,expected{k});end,end
function audit=static_log_preflight(m,names),audit=struct('logVariables',{names},'logPaths',{{}},'loggingOK',true);audit.logPaths=cell(size(names));for k=1:numel(names),b=find_system(m,'SearchDepth',1,'BlockType','ToWorkspace','VariableName',names{k});audit.logPaths{k}=b;audit.loggingOK=audit.loggingOK&&numel(b)==1;end,end
function value=macro_value(text,key),token=regexp(text,['(?m)^' key '\s+([^\r\n]+)'],'tokens','once');assert(~isempty(token),'CarSim config entry missing: %s',key);value=strtrim(token{1});end
function pathText=solver_path_from_console(text),token=regexp(text,'Use vehicle solver:\s*([^\r\n]+)','tokens','once');if isempty(token),pathText='';else,pathText=strtrim(token{1});end,end
